import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { api } from '@/lib/api';
import type { MonitoredSiteWithLatestCheck } from '@pingwatch/shared';

export function useSites() {
  const queryClient = useQueryClient();

  const sitesQuery = useQuery<MonitoredSiteWithLatestCheck[]>({
    queryKey: ['sites'],
    queryFn: () => api.getSites(),
    refetchInterval: 15000, // Poll every 15s as backup to Realtime
  });

  const deleteSiteMutation = useMutation({
    mutationFn: (siteId: string) => api.deleteSite(siteId),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['sites'] });
    },
  });

  return {
    ...sitesQuery,
    sites: sitesQuery.data || [],
    deleteSite: deleteSiteMutation.mutateAsync,
    isDeleting: deleteSiteMutation.isPending,
  };
}
